import numpy as np
import pandas as pd

df = pd.read_csv("apartments.csv")
x, y = df["area_m2"].to_numpy(), df["rent_million_vnd"].to_numpy()
z = (x - x.mean()) / x.std()                       # standardised area

def J(w, b):
    return np.mean((w * z + b - y) ** 2)

h = 1e-6
for w in (0.0, 3.17, 6.0):
    print(w, round((J(w + h, 9.0) - J(w - h, 9.0)) / (2 * h), 3))

def grad(w, b):
    error = w * z + b - y
    return float(2 * np.mean(error * z)), float(2 * np.mean(error))

print([round(g, 3) for g in grad(0.0, 0.0)], [round(g, 3) for g in grad(3.17, 9.02)])
